typedef long long ll;

static ll maxll(ll a, ll b) {
    return a > b ? a : b;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int *h = (int *)malloc((N + 1) * sizeof(int));
    ll *a = (ll *)malloc((N + 1) * sizeof(ll));
    ll *bit = (ll *)calloc((N + 2), sizeof(ll));

    for (int i = 1; i <= N; i++) scanf("%d", &h[i]);
    for (int i = 1; i <= N; i++) scanf("%lld", &a[i]);

    for (int i = 1; i <= N; i++) {
        ll best = 0;
        int x = h[i];
        for (int j = x; j > 0; j -= j & -j) {
            best = maxll(best, bit[j]);
        }

        ll cur = best + a[i];

        for (int j = x; j <= N; j += j & -j) {
            if (bit[j] < cur) bit[j] = cur;
        }
    }

    ll ans = 0;
    for (int i = 1; i <= N; i++) ans = maxll(ans, bit[i]);

    printf("%lld\n", ans);

    free(h);
    free(a);
    free(bit);
    return 0;
}

