public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());

        int[] h = new int[n];
        int[] a = new int[n];

        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            h[i] = Integer.parseInt(st.nextToken());
        }
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(st.nextToken());
        }

        // Coordinate compress heights
        int[] sortedH = h.clone();
        Arrays.sort(sortedH);
        Map<Integer, Integer> compress = new HashMap<>();
        int idx = 1;
        for (int val : sortedH) {
            if (!compress.containsKey(val)) {
                compress.put(val, idx++);
            }
        }

        int size = idx + 2;
        long[] bit = new long[size];

        // Pair heights with beauty and sort by height
        int[][] flowers = new int[n][2];
        for (int i = 0; i < n; i++) {
            flowers[i][0] = h[i];
            flowers[i][1] = a[i];
        }
        Arrays.sort(flowers, Comparator.comparingInt(o -> o[0]));

        long ans = 0;
        for (int[] f : flowers) {
            int pos = compress.get(f[0]);
            long best = query(bit, pos - 1) + f[1];
            update(bit, pos, best);
            ans = Math.max(ans, best);
        }

        System.out.println(ans);
    }

    static void update(long[] bit, int idx, long val) {
        while (idx < bit.length) {
            bit[idx] = Math.max(bit[idx], val);
            idx += idx & -idx;
        }
    }

    static long query(long[] bit, int idx) {
        long res = 0;
        while (idx > 0) {
            res = Math.max(res, bit[idx]);
            idx -= idx & -idx;
        }
        return res;
    }
}

