public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class SegTree {
        int size;
        long[] tree;

        SegTree(int n) {
            size = 1;
            while (size < n) size <<= 1;
            tree = new long[size << 1];
        }

        void update(int pos, long val) {
            int i = pos + size - 1;
            tree[i] = Math.max(tree[i], val);
            i >>= 1;
            while (i > 0) {
                tree[i] = Math.max(tree[i << 1], tree[i << 1 | 1]);
                i >>= 1;
            }
        }

        long query(int l, int r) {
            if (l > r) return 0;
            l = l + size - 1;
            r = r + size - 1;
            long res = 0;
            while (l <= r) {
                if ((l & 1) == 1) res = Math.max(res, tree[l++]);
                if ((r & 1) == 0) res = Math.max(res, tree[r--]);
                l >>= 1;
                r >>= 1;
            }
            return res;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        int[] h = new int[N];
        long[] a = new long[N];

        int maxH = 0;
        for (int i = 0; i < N; i++) {
            h[i] = fs.nextInt();
            maxH = Math.max(maxH, h[i]);
        }
        for (int i = 0; i < N; i++) {
            a[i] = fs.nextLong();
        }

        SegTree seg = new SegTree(maxH);

        for (int i = 0; i < N; i++) {
            long best = seg.query(1, h[i] - 1);
            long cur = best + a[i];
            seg.update(h[i], cur);
        }

        System.out.println(seg.query(1, maxH));
    }
}

